// Suggested questions on the Ask Amio screen (frame R30AskAmio). Learners
// tap one instead of typing (rule 1). Built only from reviewed lesson
// content the learner already studied (lesson titles and key points) and
// fixed text, never generated by AI, and nothing new is saved.

export const MAX_LESSON_SUGGESTIONS = 3;

// Before the learner has studied any lesson, and about the interview: fixed,
// the same for everyone. Keys into ASK_SCREEN_LINES (src/lib/askTutor.js),
// so they are shown in the learner's language.
export const STARTER_SUGGESTIONS = ['q_branches', 'q_constitution', 'q_rights'];
export const INTERVIEW_SUGGESTIONS = ['q_how_long', 'q_dont_understand', 'q_what_happens'];

// A key point is short enough to ask about as a word ("federal",
// "the Senate"): up to 4 words and 40 characters.
const isShortTerm = (text) => typeof text === 'string'
  && text.trim().length > 0
  && text.trim().length <= 40
  && text.trim().split(/\s+/).length <= 4;

const clean = (s) => String(s).trim().replace(/[.:;!?]+$/, '');

/**
 * Up to 3 questions from the learner's most recent lessons.
 * progress: LessonProgress rows ({ lesson_id, last_attempt_date, updated_date })
 * lessons: Lesson rows ({ id, title, key_points: [{ text }] })
 */
export function lessonSuggestions(progress = [], lessons = [], max = MAX_LESSON_SUGGESTIONS) {
  const byId = new Map(lessons.map((l) => [l.id, l]));
  const when = (p) => p.last_attempt_date || p.updated_date || p.created_date || '';
  const recent = [...progress]
    .filter((p) => byId.has(p.lesson_id))
    .sort((a, b) => String(when(b)).localeCompare(String(when(a))));

  const seenLessons = new Set();
  const terms = [];
  const titles = [];
  for (const p of recent) {
    if (seenLessons.has(p.lesson_id)) continue;
    seenLessons.add(p.lesson_id);
    if (seenLessons.size > 2) break; // the 2 most recent lessons
    const lesson = byId.get(p.lesson_id);
    const term = (lesson.key_points || []).map((k) => k?.text).find(isShortTerm);
    if (term) terms.push(`What does "${clean(term)}" mean?`);
    if (lesson.title) titles.push(`Explain "${clean(lesson.title)}" again`);
  }

  const out = [];
  for (const q of [...terms, ...titles]) {
    if (!out.includes(q)) out.push(q);
    if (out.length >= max) break;
  }
  return out;
}
